{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — are you trying to minimize the number of containers used, maximize the total weight (or value) of goods shipped, or is there another goal?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options that constitute one semantic question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "if some goods are left unshipped, is that allowed, or must every available unit of every type be loaded into the containers?"
  ],
  "rationale": "The response asks a single clarification question regarding whether unshipped goods are permitted or if all available units must be loaded."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since the goal is to use as few containers as possible and it's allowed to leave goods unshipped, is there any requirement that a minimum amount of goods must be shipped (e.g., at least X tons or at least Y units of some type), or is it acceptable to ship only a small amount in a single container as long as it meets the 18-ton minimum?"
  ],
  "rationale": "The response contains a single compound question asking for a policy choice between having a specific minimum shipment requirement or accepting a small shipment that meets the container weight limit. These are mutually exclusive options for the same underlying constraint, so they count as one independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods units indivisible (i.e., each type must be loaded in whole units per container), or can they be split fractionally?"
  ],
  "rationale": "The response asks a single clarification question regarding the divisibility of goods units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a maximum number of containers available, or can we assume an unlimited supply of containers?"
  ],
  "rationale": "The response asks a single clarification question regarding container availability constraints."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a maximum number of units of any single goods type that can be loaded into one container, or is the only per-container limit the 60-ton weight cap (plus the 18-ton minimum and the 12-unit D minimum)?"
  ],
  "rationale": "The response asks a single clarification question regarding whether there is a per-goods-type unit limit or if only the weight and minimum constraints apply."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "does this apply to every container that has A, including the case where a container has A but zero of every other type except C? In other words, is the only requirement that C ≥ 1 whenever A ≥ 1, with no other interaction between A and C?"
  ],
  "rationale": "The response asks for a single clarification regarding the scope and specific constraints of the rule linking type A and type C. Although phrased with two sentences, it seeks one specific policy confirmation."
}
